// The designer's contract files (docs/design/salvage-yard/docs/17 § 4), read from `workbench/schema/`.
// They are generated by `workbench/tools/gen_wb_schema.py`; never edit the JSON (the drift test).

import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

export const CONTRACT_DIR = fileURLToPath(new URL('../workbench/', import.meta.url));

export const PATHS = ['chat', 'mapping', 'troubleshoot', 'explain'] as const;
export type WbPath = (typeof PATHS)[number];

export type Placement = 'card' | 'stage' | 'aside' | 'conv';
export type Layout = 'inline' | 'split' | 'focus';

export interface CatalogueEntry {
  type: string;
  phase: number;
  paths: WbPath[];
  placement: Record<Layout, Placement>;
  required_bind: string[];
  bind: string[];
  props: string[];
  data: string;
  actions: string[];
  shows: string;
}

export interface Catalogue {
  limits_per_path: Record<WbPath, number>;
  components: CatalogueEntry[];
}

export interface CommandEntry {
  name: string;
  label: string;
  write: boolean;
  undo: string | null;
  api: string;
  required: string[];
  effects: string;
  stop: string;
}

export interface ToolDefinition {
  name: string;
  description: string;
  input_schema: Record<string, unknown>;
}

/** A JSON Schema document as the generator writes it. */
export type JsonSchema = Record<string, unknown> & { $id: string };

const read = <T>(name: string): T =>
  JSON.parse(readFileSync(`${CONTRACT_DIR}schema/${name}`, 'utf8')) as T;

export interface Contract {
  viewSpec: JsonSchema;
  narration: JsonSchema;
  command: JsonSchema;
  catalogue: Catalogue;
  commands: CommandEntry[];
  tools: ToolDefinition[];
}

/** Every contract file, read once per call (callers keep the result). */
export function loadContract(): Contract {
  return {
    viewSpec: read('view-spec.schema.json'),
    narration: read('narration.schema.json'),
    command: read('command.schema.json'),
    catalogue: read('catalogue.json'),
    commands: read<{ commands: CommandEntry[] }>('commands.json').commands,
    tools: read('tools.json'),
  };
}
